// Auto-generated Base64 WAV sounds — do not edit manually
import { Audio } from 'expo-av';

const B64 = {
  march0: '',
  march1: '',
  march2: '',
  march3: '',
  shoot: '',
  explosion: '',
  playerHit: '',
  ufoHit: '',
  gameover: '',
};

const loaded = {};

async function load(name) {
  if (loaded[name]) return loaded[name];
  const uri = `data:audio/wav;base64,${B64[name]}`;
  const { sound } = await Audio.Sound.createAsync({ uri });
  loaded[name] = sound;
  return sound;
}

export async function preloadSounds() {
  await Audio.setAudioModeAsync({ playsInSilentModeIOS: true });
  await Promise.all(Object.keys(B64).map(load));
}

export async function playSound(name) {
  try {
    const snd = await load(name);
    await snd.setPositionAsync(0);
    await snd.playAsync();
  } catch (_) {}
}

export async function unloadSounds() {
  for (const snd of Object.values(loaded)) {
    try { await snd.unloadAsync(); } catch (_) {}
  }
  Object.keys(loaded).forEach(k => delete loaded[k]);
}

// March rhythm — call startMarch(totalInvaders, aliveCount) each tick
let marchTimer = null;
let marchStep = 0;
const MARCH_NOTES = ['march0', 'march1', 'march2', 'march3'];

export function updateMarch(aliveCount, soundEnabled) {
  const interval = soundEnabled ? Math.max(120, 50 + aliveCount * 28) : null;
  return interval;
}

export function startMarch(interval, soundEnabled) {
  stopMarch();
  if (!soundEnabled || !interval) return;
  marchStep = 0;
  marchTimer = setInterval(() => {
    playSound(MARCH_NOTES[marchStep % 4]);
    marchStep++;
  }, interval);
}

export function stopMarch() {
  if (marchTimer) { clearInterval(marchTimer); marchTimer = null; }
}
